<?php

// API Key + HMAC-SHA256 authentication, used by the Partner Merchant Onboarding APIs.
// Each request carries two headers:
// x-gl-auth   -> your static API Key (from the PayGlocal Partner Dashboard)
// x-gl-digest -> Base64(HmacSHA256(signingInput, API_SECRET)), generated by generateDigest
// This file only generates the digest. Adding the headers to the request is left to the caller.
// No composer dependency is needed, hash_hmac is part of PHP core (PHP 7.1+).

// Selects the input that has to be signed
// GET -> request URI path (including query string if present)
// POST / PUT -> exact raw request body
function getSigningInput($httpMethod, $requestUri, $payload)
{
    if (strtoupper($httpMethod) === 'GET') {
        return $requestUri;
    }
    return $payload;
}

// $httpMethod : HTTP method of the request (GET, POST, PUT)
// $requestUri : request URI path, including the query string if present, no host or scheme (used for GET)
//               e.g. /gcc/v2/partner/merchant/onboard/business-category
// $payload    : exact raw request body (json stringified), used for POST / PUT. Compute the digest over the
//               same string you send as the body, any difference in whitespace or field order fails with 401
// $apiSecret  : API Secret of the partner (Downloaded from the PayGlocal Partner Dashboard), never the API Key
// returns the Base64 encoded HmacSHA256 digest
function generateDigest($httpMethod, $requestUri, $payload, $apiSecret)
{
    if ($apiSecret === null || $apiSecret === '') {
        throw new InvalidArgumentException('Please provide API secret');
    }

    $signingInput = getSigningInput($httpMethod, $requestUri, $payload);
    if ($signingInput === null || $signingInput === '') {
        throw new InvalidArgumentException('Please provide request URI for GET and payload for POST / PUT');
    }

    return base64_encode(hash_hmac('sha256', $signingInput, $apiSecret, true));
}

// Usage:
// require 'digest.php';
//
// GET  : $digest = generateDigest('GET', '/gcc/v2/partner/merchant/onboard/business-category', null, $apiSecret);
// POST : $body = json_encode($payload); // send this exact string as the request body
//        $digest = generateDigest('POST', '/gcc/v2/partner/merchant/onboard', $body, $apiSecret);
//
// then send the headers 'x-gl-auth: ' . $apiKey and 'x-gl-digest: ' . $digest
